const {test}=require('node:test');
const assert=require('node:assert/strict');
const {grossCents}=require('../src/checkout.cjs');
test('extends quantities before invoice VAT rounding',()=>{
 assert.equal(grossCents([{unitCents:99,quantity:3}],2000),356);
 assert.equal(grossCents([{unitCents:1,quantity:1},{unitCents:1,quantity:1}],5000),3);
 assert.equal(grossCents([{unitCents:1,quantity:1}],5000),2);
 assert.equal(grossCents([{unitCents:999,quantity:0}],2000),0);
 assert.equal(grossCents([],2000),0);
});
test('safe bounds are exact and invalid baskets fail',()=>{
 assert.equal(grossCents([{unitCents:Number.MAX_SAFE_INTEGER,quantity:1}],0),Number.MAX_SAFE_INTEGER);
 for(const vat of [-1,1.5,NaN,Infinity,undefined]) assert.throws(()=>grossCents([],vat));
 for(const line of [{unitCents:-1,quantity:1},{unitCents:1.2,quantity:1},{unitCents:1,quantity:-1},{unitCents:1,quantity:1.1},{unitCents:1,quantity:Number.MAX_SAFE_INTEGER+1},null]) assert.throws(()=>grossCents([line],2000));
 assert.throws(()=>grossCents([{unitCents:Number.MAX_SAFE_INTEGER,quantity:2}],0));
 assert.throws(()=>grossCents([{unitCents:Number.MAX_SAFE_INTEGER,quantity:1}],1));
 assert.throws(()=>grossCents(null,0));
});
